Here is a Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    def __init__(self, data: List[Any]):
        self.data = data

    # Template Method - defines the skeleton
    def sort(self) -> List[Any]:
        self._before_sort()
        self._do_sort()
        self._after_sort()
        return self.data

    def _before_sort(self):
        print(f"Starting sort with {len(self.data)} items")

    def _after_sort(self):
        print(f"Finished sort")

    @abstractmethod
    def _do_sort(self):
        pass

    # Primitive operations to be used by subclasses
    def compare(self, a: Any, b: Any) -> bool:
        return a > b

    def swap(self, i: int, j: int):
        self.data[i], self.data[j] = self.data[j], self.data[i]

    def __repr__(self):
        return str(self.data)


class BubbleSort(SortAlgorithm):
    def _do_sort(self):
        n = len(self.data)
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(self.data[j], self.data[j + 1]):
                    self.swap(j, j + 1)
                    swapped = True
            if not swapped:
                break


class SelectionSort(SortAlgorithm):
    def _do_sort(self):
        n = len(self.data)
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(self.data[min_idx], self.data[j]):
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    nums = [64, 25, 12, 22, 11]
    strs = ["banana", "apple", "cherry", "date"]

    print("Bubble Sort ints:", BubbleSort(nums.copy()).sort())
    print("Selection Sort ints:", SelectionSort(nums.copy()).sort())
    print("Bubble Sort strs:", BubbleSort(strs.copy()).sort())
    print("Selection Sort strs:", SelectionSort(strs.copy()).sort())
```

The `SortAlgorithm` abstract class defines the template method `sort()` and the primitive operations `compare()` and `swap()`. `BubbleSort` and `SelectionSort` provide their own `_do_sort()` implementations while reusing the common skeleton.

